                          [cap_od2 / 2 + wall, taper_lead_in - d / 2],
                          [cap_od2 / 2 + wall, -d / 2],
                          [0, -d / 2]
                      ]);
                  }
              }
              down(d / 2){
                  generic_bottle_cap(
                      orient = DOWN,
                      wall = wall,
                      texture = texture,
