// Arguments:
//   size = size of hose part, must be 1/4, 1/2 or 3/4
//   outer = set to true to get the outer radius.  Default: false
// Example(3D):
//   $fn=64;
//   back_half()
//      diff("remove")
//        cuboid(50){
